update notification_record
set sent_at = #{sentAt}, expires_at = #{expiresAt}, update_time = #{sentAt}
where record_id = #{recordId} and sent_at is null

update notification_record
set status = #{status}, success_count = #{successCount}, fail_count = #{failCount},
    total_count = #{totalCount}, update_time = #{updateTime}
where record_id = #{recordId}

update notification_record
set status = #{status}, update_time = #{updateTime}
where record_id = #{recordId} and deleted = '0'

update notification_record
set revoked = '1', revoked_time = #{revokedTime}, revoked_by = #{revokedBy}, update_time = #{revokedTime}
where record_id = #{recordId} and deleted = '0'

